base:
//! Service configuration for the capybase agent.
//!
//! Centralizes tunables. Both branches edit this module's `Config` struct
//! to exercise Rust merge conflicts inside an `impl` block.

pub struct Config {
    pub name: String,
    pub max_retries: u32,
}

impl Config {
    pub fn new() -> Self {
        Config {
            name: "capybase".to_string(),
            max_retries: 3,
        }
    }

    pub fn label(&self) -> String {
        format!("{} (retries={})", self.name, self.max_retries)
    }
}

